    yamlFilename: "05-external-destinations.yaml",
    yamlCode:
      '# Single-Node OpenShift destinations. Paths, hosts, and credentials are\n# satisfied by the manifests under examples/integrations/oran-telco-pipeline/openshift/.\noutput:\n  broker:\n    pattern: fan_out\n    outputs:\n      # Observability: OTLP/HTTP to the OpenTelemetry Collector on the node.\n      # OpenShift user-workload monitoring scrapes the collector (ServiceMonitor).\n      - label: otel_collector\n        processors:\n          - mapping: |\n              root = {\n                "resourceMetrics": [\n                  {\n                    "resource": {\n                      "attributes": [\n                        {\n                          "key": "cell_id",\n                          "value": {\n                            "stringValue": this.cell_id\n                          }\n                        },\n                        {\n                          "key": "region",\n                          "value": {\n                            "stringValue": this.region\n                          }\n                        }\n                      ]\n                    },\n                    "scopeMetrics": [\n                      {\n                        "scope": {\n                          "name": "oran.telemetry",\n                          "version": "2.0.0"\n                        },\n                        "metrics": [\n                          {\n                            "name": "oran_ptp_offset_nanoseconds",\n                            "unit": "ns",\n                            "gauge": {\n                              "dataPoints": [\n                                {\n                                  "timeUnixNano": (this.timestamp * 1000000000).floor().string(),\n                                  "asInt": this.ptp_offset_ns\n                                }\n                              ]\n                            }\n                          },\n                          {\n                            "name": "oran_cpu_utilization_percent",\n                            "unit": "%",\n                            "gauge": {\n                              "dataPoints": [\n                                {\n                                  "timeUnixNano": (this.timestamp * 1000000000).floor().string(),\n                                  "asDouble": this.cpu_percent\n                                }\n                              ]\n                            }\n                          },\n                          {\n                            "name": "oran_prb_utilization_percent",\n                            "unit": "%",\n                            "gauge": {\n                              "dataPoints": [\n                                {\n                                  "timeUnixNano": (this.timestamp * 1000000000).floor().string(),\n                                  "asDouble": this.prb_dl_util_percent,\n                                  "attributes": [\n                                    {\n                                      "key": "direction",\n                                      "value": {\n                                        "stringValue": "downlink"\n                                      }\n                                    }\n                                  ]\n                                },\n                                {\n                                  "timeUnixNano": (this.timestamp * 1000000000).floor().string(),\n                                  "asDouble": this.prb_ul_util_percent,\n                                  "attributes": [\n                                    {\n                                      "key": "direction",\n                                      "value": {\n                                        "stringValue": "uplink"\n                                      }\n                                    }\n                                  ]\n                                }\n                              ]\n                            }\n                          },\n                          {\n                            "name": "oran_rsrp_dbm",\n                            "unit": "dBm",\n                            "gauge": {\n                              "dataPoints": [\n                                {\n                                  "timeUnixNano": (this.timestamp * 1000000000).floor().string(),\n                                  "asDouble": this.rsrp_dbm\n                                }\n                              ]\n                            }\n                          },\n                          {\n                            "name": "oran_sinr_db",\n                            "unit": "dB",\n                            "gauge": {\n                              "dataPoints": [\n                                {\n                                  "timeUnixNano": (this.timestamp * 1000000000).floor().string(),\n                                  "asDouble": this.sinr_db\n                                }\n                              ]\n                            }\n                          }\n                        ]\n                      }\n                    ]\n                  }\n                ]\n              }\n        fallback:\n          - http_client:\n              url: "${OTEL_ENDPOINT:http://oran-collector.oran-telemetry.svc:4318}/v1/metrics"\n              verb: POST\n              headers:\n                Content-Type: application/json\n          - file:\n              path: \'/data/dead-letter/otel-${! now().ts_format("2006-01-02") }.jsonl\'\n              codec: lines\n\n      # Storage: Parquet files on the PersistentVolumeClaim mounted at /data.\n      - label: parquet_pvc\n        broker:\n          batching:\n            count: 1000\n            period: 300s\n            processors:\n              - parquet_encode:\n                  default_compression: zstd\n                  schema:\n                    - { name: timestamp, type: INT64 }\n                    - { name: cell_id, type: UTF8 }\n                    - { name: site_name, type: UTF8 }\n                    - { name: region, type: UTF8 }\n                    - { name: ptp_offset_ns, type: INT64, optional: true }\n                    - { name: cpu_percent, type: DOUBLE, optional: true }\n                    - { name: prb_dl_util_percent, type: DOUBLE, optional: true }\n                    - { name: prb_ul_util_percent, type: DOUBLE, optional: true }\n                    - { name: rsrp_dbm, type: DOUBLE, optional: true }\n                    - { name: sinr_db, type: DOUBLE, optional: true }\n                    - { name: timing_review, type: UTF8, optional: true }\n                    - name: review_reasons\n                      type: LIST\n                      optional: true\n                      fields:\n                        - { name: element, type: UTF8 }\n          outputs:\n            - file:\n                path: \'/data/oran-telemetry/date=${! now().ts_format("2006-01-02") }/part-${! uuid_v4() }.parquet\'\n                codec: all-bytes\n\n      # Analytics: AMQ Streams (Strimzi) Kafka, TLS listener on 9093,\n      # cluster CA mounted from the operator-managed Secret.\n      - label: amq_streams_kafka\n        kafka:\n          addresses: ["${KAFKA_BOOTSTRAP_SERVERS:oran-kafka-kafka-bootstrap.oran-telemetry.svc:9093}"]\n          topic: oran-telemetry-alerts\n          key: \'${! this.cell_id }\'\n          tls:\n            enabled: true\n            root_cas_file: /etc/expanso/kafka-ca/ca.crt\n          sasl:\n            mechanism: SCRAM-SHA-512\n            user: "${KAFKA_USERNAME}"\n            password: "${KAFKA_PASSWORD}"\n          ack_replicas: true\n',
